import gurobipy as gp
from gurobipy import GRB
platforms = []
capacities = {}
genres = []
values = {}
requirements = {}
for rec in LEGACY_RECORDS:
    src = rec['source']
    vals = rec['values']
    if src.endswith('capacity.csv'):
        pid = vals['resource_id']
        platforms.append(pid)
        capacities[pid] = int(vals['resource_capacity'])
    elif src.endswith('products.csv'):
        gname = vals['item_name']
        genres.append(gname)
        values[gname] = int(vals['item_value'])
        requirements[gname] = int(vals['resource_requirement'])
if len(platforms) == 0 or len(genres) == 0:
    raise ValueError('Missing platforms or genres in LEGACY_RECORDS')
for pid in platforms:
    if pid not in capacities:
        raise ValueError(f'Missing capacity for platform {pid}')
for g in genres:
    if g not in values or g not in requirements:
        raise ValueError(f'Missing value or requirement for genre {g}')
m = gp.Model('VideoGameStore_Allocation')
x_vars = m.addVars(platforms, genres, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[g] * x_vars[p, g] for p in platforms for g in genres)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((requirements[g] * x_vars[p, g] for g in genres)) <= capacities[p] for p in platforms), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')